// Des: Tests for flow data: queue order, approvals, resume, marks
// Flo: memory store > flows and items > assert states
// I/O: rows > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const data = @import("st-stat-data.zig"); const flo = @import("st-flow-data.zig"); const T = std.testing;
fn opn() !data.Stor { return data.Stor.open(T.allocator, ":memory:"); }
test "latest flow, items in sequence, low risk is auto-approved, ask is not" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try T.expect((try flo.flowLatest(&sto, alo)) == null); const one = try flo.flowNew(&sto, "u1", "morning", 100); const two = try flo.flowNew(&sto, "u2", "evening", 200); _ = try flo.itemAdd(&sto, two, 2, "send", "Mom|hi", "low", 1); _ = try flo.itemAdd(&sto, two, 1, "group", "Fam", "ask", 1); _ = try flo.itemAdd(&sto, one, 1, "read", "", "low", 1); const lat = (try flo.flowLatest(&sto, alo)).?; try T.expectEqual(two, lat.id); try T.expectEqualStrings("plan", lat.state); const its = try flo.itemsOf(&sto, alo, two); try T.expectEqual(@as(usize, 2), its.len); try T.expectEqualStrings("group", its[0].job); try T.expect(!its[0].appr); try T.expect(its[1].appr); }
test "next skips done and skip, approve is once, skip becomes todo again" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const fl = try flo.flowNew(&sto, "u", "f", 1); const a = try flo.itemAdd(&sto, fl, 1, "pin", "Boss", "low", 1); const b = try flo.itemAdd(&sto, fl, 2, "group", "Fam", "ask", 1); const c = try flo.itemAdd(&sto, fl, 3, "send", "x|y", "low", 1); try flo.itemSet(&sto, a, "done", ""); try flo.itemSet(&sto, b, "skip", "not approved"); const nx = (try flo.itemNext(&sto, alo, fl)).?; try T.expectEqual(c, nx.id); try T.expect(try flo.itemApprove(&sto, b)); try T.expect(!try flo.itemApprove(&sto, b)); const nx2 = (try flo.itemNext(&sto, alo, fl)).?; try T.expectEqual(b, nx2.id); try T.expectEqualStrings("todo", nx2.state); try T.expect(nx2.appr); try flo.itemSet(&sto, b, "done", ""); try flo.itemSet(&sto, c, "done", ""); try T.expect((try flo.itemNext(&sto, alo, fl)) == null); try T.expectError(error.Fail, flo.itemSet(&sto, 9999, "done", "")); }
test "wait and doing rows are resumed, tries count up" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const fl = try flo.flowNew(&sto, "u", "f", 1); const a = try flo.itemAdd(&sto, fl, 1, "send", "a|b", "low", 1); _ = try flo.itemAdd(&sto, fl, 2, "send", "c|d", "low", 1); try flo.itemSet(&sto, a, "wait", "captcha"); try flo.itemTry(&sto, a); try flo.itemTry(&sto, a); const nx = (try flo.itemNext(&sto, alo, fl)).?; try T.expectEqual(a, nx.id); try T.expectEqualStrings("wait", nx.state); try T.expectEqual(@as(i64, 2), nx.tries); try T.expectEqualStrings("captcha", nx.note); }
test "approve all counts only unapproved items; flow state changes" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const fl = try flo.flowNew(&sto, "u", "f", 1); _ = try flo.itemAdd(&sto, fl, 1, "group", "a", "ask", 1); _ = try flo.itemAdd(&sto, fl, 2, "forward", "b", "ask", 1); _ = try flo.itemAdd(&sto, fl, 3, "read", "", "low", 1); try T.expectEqual(@as(u32, 2), try flo.approveAll(&sto, fl)); try T.expectEqual(@as(u32, 0), try flo.approveAll(&sto, fl)); try flo.flowSet(&sto, fl, "run"); try T.expectEqualStrings("run", (try flo.flowLatest(&sto, alo)).?.state); try T.expectError(error.Fail, flo.flowSet(&sto, 999, "x")); }
test "failed chat marks expire by time window" { var sto = try opn(); defer sto.close(); try T.expect(!try flo.chatFailedSince(&sto, "Mom", 0)); try flo.chatFailMark(&sto, "Mom", 1000); try T.expect(try flo.chatFailedSince(&sto, "Mom", 999)); try T.expect(!try flo.chatFailedSince(&sto, "Mom", 1000)); try T.expect(!try flo.chatFailedSince(&sto, "Boss", 0)); }
test "meta ints with default and bad text" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try T.expectEqual(@as(i64, 7), try flo.metaInt(&sto, alo, "k", 7)); try flo.metaPutInt(&sto, "k", -5); try T.expectEqual(@as(i64, -5), try flo.metaInt(&sto, alo, "k", 7)); try sto.metaSet("k", "oops"); try T.expectEqual(@as(i64, 7), try flo.metaInt(&sto, alo, "k", 7)); }
